585	// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
586	// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
587	__device__ __forceinline__ int koff8(int row, int c) {
588	    return (c >> 7) * (128 * CTA_N) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
589	}
590	constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
