594	// FA3 warp-scheduler ping-pong primitives (mainloop_fwd_sm90_tma_gmma_ws.hpp). A named barrier with
595	// an explicit arrival count: one consumer WG `bar.sync`s it (contributes its 128 threads + blocks)
596	// while the other WG `bar.arrive`s it (contributes 128, no block). With cnt = 256 the syncing WG
597	// unblocks only once the other WG arrives -> the two consumer WGs alternate their wgmma-issue phase
598	// by one step, so while WG_a runs softmax on the SFU, WG_b feeds the tensor core (and vice-versa).
599	__device__ __forceinline__ void nb_sync(int id, int cnt) {
600	    asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
601	}
602	__device__ __forceinline__ void nb_arrive(int id, int cnt) {
