605	// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
606	template <int HDt>
607	__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
608	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
609	#pragma unroll
610	    for (int kb = 0; kb < HDt / 32; ++kb) {
611	        uint32_t off = (uint32_t)(kb * 32);
612	        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
613	        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
614	        int scaleD = (kb == 0) ? 0 : 1;
615	        asm volatile(
616	        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
617	        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
618	        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
