646	// FA3 register-source P (MmaPV_is_RS): build the fp8 A-operand registers from the f32 softmax
647	// probabilities s[64] (C-accumulator layout) WITHOUT the smem scatter+barrier round-trip. Pack each
648	// c-group's 4 f32 ((p,r2) combined, convert_layout_acc_Aregs order) -> P16[c], then permute_Aregs_fp8
649	// (quad __shfl + byte_perm) fixes the register layout to the wgmma A operand. Validated bit-exact vs
650	// the SS path in kernels/fp8_probe.cu (PV-RS). tg=lane&3, group=lane>>2.
651	__device__ __forceinline__ void build_P_rs_fp8(const float (&s)[64], uint32_t (&P16)[16], int tg, int group) {
652	#pragma unroll
653	    for (int c = 0; c < 16; ++c) {
654	        __nv_fp8_e4m3 e0(s[c*4+0]), e1(s[c*4+1]), e2(s[c*4+2]), e3(s[c*4+3]);
655	        P16[c] = (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
656	    }
657	    const bool lane_03 = (tg == 0 || tg == 3);
658	    const int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
659	    const int up = (tg == 0) ? 0 : (tg == 1) ? 3 : (tg == 2) ? 1 : 2;   // upper_map[tg]
660	    const int src_hi = group * 4 + up, src_lo = group * 4 + (up ^ 1);
661	#pragma unroll
662	    for (int u = 0; u < 8; ++u) {
663	        uint32_t upper = P16[2*u + 0], lower = P16[2*u + 1];
664	        uint32_t upper0 = lane_03 ? upper : lower;
665	        uint32_t lower0 = lane_03 ? lower : upper;
666	        upper0 = __shfl_sync(0xffffffffu, upper0, src_hi, 32);
667	        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
668	        P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
669	        P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
670	    }
671	}
