756	// Gather one row (HDt elems) of K-major data from gmem into the swizzled smem tile (16-bit TC), OR
757	// zero it. TIn is the gmem element type: when TIn==TC (bf16/fp16) it is a raw 16-byte copy (cp.async
758	// or store); when TIn is fp8-e4m3 each 8-elem chunk is loaded, converted to TC (bf16) and stored
759	// (TMA/cp.async can't convert ⇒ fp8 always takes the synchronous convert-store path).
760	template <typename TIn, typename TC, int HDt, int ROWS = CTA_N>
761	__device__ __forceinline__ void gather_row_k(TC* sbase, uint32_t sbase_addr, int row,
762	                                             const TIn* src, bool valid) {
763	#pragma unroll
764	    for (int c8 = 0; c8 < HDt / 8; ++c8) {
765	        int o = koffR<ROWS>(row, c8 * 8);
766	        if (!valid) { *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0); continue; }
767	        if constexpr (std::is_same<TIn, TC>::value) {
768	#if PF_CPASYNC
769	            cp_async_16(sbase_addr + (uint32_t)(o * 2), src + c8 * 8);
770	#else
771	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(src + c8 * 8);
772	#endif
773	        } else {
774	            uint2 raw = *reinterpret_cast<const uint2*>(src + c8 * 8);   // 8 fp8 in ONE coalesced load
775	            const TIn* f = reinterpret_cast<const TIn*>(&raw);
776	            TC tmp[8];
777	#pragma unroll
778	            for (int e = 0; e < 8; ++e) tmp[e] = from_float<TC>(to_float<TIn>(f[e]));
779	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(tmp);
780	        }
781	    }
782	}
