2465	// FAST PATH 2: decode (q_len small), flash-decoding with split-KV.
2466	//
2467	// Memory-bound regime (the QK/PV are tiny GEMVs; the bottleneck is streaming the paged KV cache).
2468	// One WARP per (batch, kv_head, kv_split) work-item; 128-thread blocks pack 4 independent warps.
2469	// A warp processes ALL packed-GQA rows (M = q_len * rep) of its (b,hk) over its key slice, with
2470	// lane L owning the contiguous head-dim chunk [L*per, L*per+per) so K/V loads are 256 B coalesced and
2471	// the QK dot is a single warp reduction. Each warp writes a NORMALIZED partial (O_s, lse_s) to scratch;
2472	// `combine_kernel` does the across-split flash reduction. Matches the scalar fallback semantics
2473	// (qk_scale = scale*qd*kd, softcap after scale, causal + sliding-window, q_abs = klen - sq + qpos).
2474	namespace dec {
2475	constexpr int WARP = 32, WARPS_PER_BLOCK = 4, DEC_THREADS = WARP * WARPS_PER_BLOCK;
2476	
2477	__device__ __forceinline__ float wreduce_sum(float v) {
2478	#pragma unroll
2479	    for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
2480	    return v;
2481	}
2482	
2483	// One warp = one (b, hk, split). MAXM bounds the packed-GQA rows; per/perv = HD/32, HDV/32 dims/lane.
2484	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2485	__global__ void decode_kernel(
2486	        const TIn* __restrict__ Q, const TIn* __restrict__ K, const TIn* __restrict__ V,
2487	        float* __restrict__ Opart, float* __restrict__ LSEpart,
2488	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
2489	        const int* __restrict__ page_table,
2490	        const float* __restrict__ q_descale, const float* __restrict__ k_descale, const float* __restrict__ v_descale,
2491	        int ds_b, int ds_h,
2492	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2493	        int batch, int hq, int hkv, int rep, int total_q, int block_size, int page_stride,
2494	        int num_splits, float scale, float softcap, int win_l, int win_r, int causal) {
2495	    constexpr int per = HD / 32, perv = HDV / 32;
2496	    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
2497	    const int lane = threadIdx.x & 31;
2498	    if (witem >= num_splits * hkv * batch) return;
2499	    // work-item -> (b, hk, split)
2500	    const int split = witem % num_splits;
2501	    int tmp = witem / num_splits;
2502	    const int hk = tmp % hkv;
2503	    const int b = tmp / hkv;
2504	    // b is bounded by the launch (grid sized to batch); guard:
2505	    const int q0 = cu_q[b];
2506	    const int sq = cu_q[b + 1] - q0;
2507	    if (sq <= 0) return;
2508	    const int klen = seqused_k ? seqused_k[b] : (cu_k[b + 1] - cu_k[b]);
2509	    const int M = sq * rep;
2510	
2511	    const long ds_idx = (long)b * ds_b + (long)hk * ds_h;
2512	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
2513	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
2514	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
2515	    const float qk_scale = scale * qd * kd;
2516	
2517	    // split's key range
2518	    const int span = (klen + num_splits - 1) / num_splits;
2519	    const int jlo = split * span;
2520	    const int jhi = min(jlo + span, klen);
2521	
2522	    float qreg[MAXM][per];
2523	    float acc[MAXM][perv];
2524	    float mrow[MAXM], lrow[MAXM];
2525	    int qabs[MAXM];
2526	#pragma unroll
2527	    for (int mi = 0; mi < MAXM; ++mi) {
2528	        if (mi >= M) break;
2529	        const int qpos = mi / rep, r = mi % rep;
2530	        const int head = hk * rep + r;
2531	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2532	#pragma unroll
2533	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2534	#pragma unroll
2535	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
2536	        mrow[mi] = -INFINITY; lrow[mi] = 0.f;
2537	        qabs[mi] = klen - sq + qpos;
2538	    }
2539	
2540	    // Software-pipelined K/V load: issue key (j+1)'s gmem loads (including the dependent page_table
2541	    // lookup) while computing on key j, so the load latency overlaps the (short) softmax compute.
2542	    auto load_key = [&](int j, float* kx, float* vx) {
2543	        long krow;
2544	        if (page_table) { int blk = page_table[(long)b * page_stride + j / block_size]; krow = (long)blk * block_size + (j % block_size); }
2545	        else            { krow = (long)cu_k[b] + j; }
2546	        const TIn* kp = K + krow * k_row + (long)hk * k_head;
2547	        const TIn* vp = V + krow * v_row + (long)hk * v_head;
2548	#pragma unroll
2549	        for (int e = 0; e < per; ++e)  kx[e] = to_float<TIn>(kp[lane * per + e]);
2550	#pragma unroll
2551	        for (int e = 0; e < perv; ++e) vx[e] = to_float<TIn>(vp[lane * perv + e]);
2552	    };
2553	    float kxA[per], vxA[perv], kxB[per], vxB[perv];
2554	    if (jlo < jhi) load_key(jlo, kxA, vxA);
2555	    for (int j = jlo; j < jhi; ++j) {
2556	        const bool A = ((j - jlo) & 1) == 0;
2557	        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
2558	        if (j + 1 < jhi) load_key(j + 1, A ? kxB : kxA, A ? vxB : vxA);   // prefetch next
2559	#pragma unroll
2560	        for (int mi = 0; mi < MAXM; ++mi) {
2561	            if (mi >= M) break;
2562	            const int qa = qabs[mi];
2563	            bool masked = (causal && j > qa) || (win_l >= 0 && j < qa - win_l) || (win_r >= 0 && j > qa + win_r);
2564	            float dot = 0.f;
2565	#pragma unroll
2566	            for (int e = 0; e < per; ++e) dot += qreg[mi][e] * kx[e];
2567	            float s = wreduce_sum(dot) * qk_scale;
2568	            if (softcap > 0.f) s = softcap * tanhf(s / softcap);
2569	            if (masked) continue;
2570	            float mnew = fmaxf(mrow[mi], s);
2571	            float corr = __expf(mrow[mi] - mnew), p = __expf(s - mnew);
2572	            lrow[mi] = lrow[mi] * corr + p;
2573	#pragma unroll
2574	            for (int e = 0; e < perv; ++e) acc[mi][e] = acc[mi][e] * corr + p * (vx[e] * vd);
2575	            mrow[mi] = mnew;
2576	        }
2577	    }
2578	
2579	#pragma unroll
2580	    for (int mi = 0; mi < MAXM; ++mi) {
2581	        if (mi >= M) break;
2582	        const int qpos = mi / rep, r = mi % rep;
2583	        const int head = hk * rep + r, qidx = q0 + qpos;
2584	        const float inv = lrow[mi] > 0.f ? 1.f / lrow[mi] : 0.f;
2585	        float* op = Opart + (((long)split * total_q + qidx) * hq + head) * HDV;
2586	#pragma unroll
2587	        for (int e = 0; e < perv; ++e) op[lane * perv + e] = acc[mi][e] * inv;
2588	        if (lane == 0)
2589	            LSEpart[((long)split * hq + head) * total_q + qidx] =
2590	                (lrow[mi] > 0.f) ? (mrow[mi] + __logf(lrow[mi])) : -INFINITY;
2591	    }
2592	}
2593	
2594	// Flash-combine the per-split normalized partials into the final O/LSE.
2595	// The old kernel ran one WARP per (qidx,head) looping serially over splits, so for small
2596	// batch*heads only a few dozen warps were resident -> the cross-split reduce was DRAM-latency
2597	// starved (~40% of decode time, DRAM <2% on hd256). Here:
2598	//   * grid = (total_q*hq, NB): each (qidx,head) is split into NB ~64-elem HDV tiles -> NB x more
2599	//     resident blocks so the strided per-split O loads have enough warps to hide latency.

2336	static void launch_prefill_fp8_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2337	                                 at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2338	                                 const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2339	                                 const std::optional<at::Tensor>& page_table, int hkv, int rep, int total_q,
2340	                                 int block_size, int page_stride, int tiles_m, int b, double scale, bool causal,
2341	                                 double softcap, int win_l, int win_r,
2342	                                 long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2343	                                 long o_row, long o_head, int num_splits, float* Opart, float* LSEpart,
2344	                                 const float* qd, const float* kd, const float* vd, int ds_b, int ds_h,
2345	                                 cudaStream_t stream) {
2346	    const bool paged = page_table.has_value();
2347	    // Persistent continuous-ring fp8 prefill: collapses the per-tile grid's ~8.7 waves into 1 (the fp8
2348	    // dense config's 38% long_scoreboard was the per-CTA cold-start that the streamed K/V ring hides).
2349	    // (A deeper PSTG=4 ring fits at 1-byte fp8 -- 16384*14=224KB -- but only moved 0.817->0.820, so the
2350	    // remaining gap is the SS-PV smem round-trip / V-transpose, not ring depth; kept at STAGES=3.)
2351	    // Scoped to non-paged + num_splits==1 (paged/split/varlen stay on the per-tile grid below).
2352	    if (!paged && num_splits <= 1) {
2353	        static int num_sm = 0;
2354	        if (num_sm == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&num_sm, cudaDevAttrMultiProcessorCount, dev); if (num_sm <= 0) num_sm = 132; }
2355	        const long total_work = (long)tiles_m * hkv * b;
2356	        if (total_work >= 2L * num_sm) {
2357	            constexpr int QBUF = 1, SDEPTH = 2;   // must match prefill_fp8_persist_kernel
2358	            constexpr int HDQK = (HD < 128) ? 128 : HD;   // K/Q 128-wide (koff8 row*128); see fp8 kernel
2359	            int smem_p = (int)(QBUF * CTA_M * HDQK + STAGES * CTA_N * HDQK + STAGES * HDV * CTA_N + CTA_M * CTA_N
2360	                               + STAGES * CTA_N * HDV)
2361	                         + (3 * STAGES + 2 * QBUF + 2 * SDEPTH) * (int)sizeof(uint64_t) + SDEPTH * (int)sizeof(int);
2362	            auto wctr = at::empty({1}, q.options().dtype(at::kInt));
2363	            cudaMemsetAsync(wctr.data_ptr<int>(), 0, sizeof(int), stream);
2364	            // fp8 TMA maps: K swizzled (koff8, [128,CTA_N] box) + V-staging plain ([128,CTA_N], no swz).
2365	            // Requires contiguous heads (stride(1)==hd). Falls back below if not TMA-eligible.
2366	            const bool fp8_tma_ok = (HD == 128 && HDV == 128) &&
2367	                                    (k.stride(2) == 1 && v.stride(2) == 1 &&
2368	                                     k.stride(1) == (int64_t)HD && v.stride(1) == (int64_t)HDV);
2369	            if (fp8_tma_ok) {
2370	                CUtensorMap mapK = make_fp8_contig(k, CTA_N, true);
2371	                CUtensorMap mapVst = make_fp8_contig(v, CTA_N, false);
2372	                static bool attr_set_p = false;
2373	                if (!attr_set_p) { cudaFuncSetAttribute(prefill_fp8_persist_kernel<HD, HDV, EXTRA, STAGES>, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_p); attr_set_p = true; }
2374	                const unsigned gx = (unsigned)(total_work < (long)num_sm ? total_work : (long)num_sm);
2375	                prefill_fp8_persist_kernel<HD, HDV, EXTRA, STAGES><<<dim3(gx, 1, 1), NThreads, smem_p, stream>>>(
2376	                    (const __nv_fp8_e4m3*)q.data_ptr(), (const __nv_fp8_e4m3*)k.data_ptr(), (const __nv_fp8_e4m3*)v.data_ptr(),
2377	                    (__nv_bfloat16*)out.data_ptr(), (float*)lse.data_ptr(),
2378	                    (const int*)cu_q.data_ptr(), cu_k ? (const int*)cu_k->data_ptr() : nullptr,
2379	                    seqused_k ? (const int*)seqused_k->data_ptr() : nullptr,
2380	                    q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,
2381	                    hkv, rep, total_q, (float)scale, causal ? 1 : 0, (float)softcap, win_l, win_r,
2382	                    qd, kd, vd, ds_b, ds_h, tiles_m, b, wctr.data_ptr<int>(), mapK, mapVst);
2383	                return;
2384	            }
2385	            // !fp8_tma_ok -> fall through to the per-tile cp.async path below.
2386	        }
2387	    }
2388	    // + STAGES*CTA_N*HDV for the plain V-staging ring (TMA/cp.async target, transposed in-smem to sVt);
2389	    // + STAGES extra barriers (loaded[]) for the K/V delivered signal.
2390	    constexpr int HDQK_ = (HD < 128) ? 128 : HD;   // K/Q 128-wide (koff8 row*128); see prefill_fp8_kernel
2391	    int smem = (int)(CTA_M * HDQK_ + STAGES * CTA_N * HDQK_ + STAGES * HDV * CTA_N + CTA_M * CTA_N
2392	                     + STAGES * CTA_N * HDV)
2393	               + (3 * STAGES + 1) * (int)sizeof(uint64_t);
2394	    dim3 grid((unsigned)(tiles_m * num_splits), (unsigned)hkv, (unsigned)b);
2395	    // TMA-eligible? paged: block_size composes with the 128B swizzle (|CTA_N, %8) + contiguous heads;
2396	    // non-paged: contiguous heads. TMA offloads the per-key cp.async gather (long_scoreboard-bound) to
2397	    // the TMA engine -- the same fix that took fp8 dense 0.84->1.0; fp8 decode is load-bound too.
2398	    // The fp8 TMA box is hardcoded 128-wide (128 fp8 = one 128B swizzle row), so it is valid ONLY for
2399	    // HD==HDV==128; a 64-wide head would over-read into the next head / past the tensor. hd64 fp8 falls
2400	    // to the cp.async gather (loads exactly HD cols into the HDQK=128-padded koff8 tile).
2401	    bool fp8_tma_ok = (HD == 128 && HDV == 128) && (paged
2402	        ? (block_size > 0 && (CTA_N % block_size == 0) && (block_size % 8 == 0) &&
2403	           k.stride(3) == 1 && v.stride(3) == 1 && k.stride(2) == (int64_t)HD && v.stride(2) == (int64_t)HDV)
2404	        : (k.stride(2) == 1 && v.stride(2) == 1 && k.stride(1) == (int64_t)HD && v.stride(1) == (int64_t)HDV));
2405	#define FP8K_LAUNCH(TMA_, MK_, MV_)                                                                      \
2406	    do {                                                                                                \
2407	        static bool as_##TMA_ = false;                                                                  \
2408	        if (!as_##TMA_) { cudaFuncSetAttribute(prefill_fp8_kernel<HD, HDV, EXTRA, STAGES, TMA_>, cudaFuncAttributeMaxDynamicSharedMemorySize, smem); as_##TMA_ = true; } \
2409	        prefill_fp8_kernel<HD, HDV, EXTRA, STAGES, TMA_><<<grid, NThreads, smem, stream>>>(             \
2410	            (const __nv_fp8_e4m3*)q.data_ptr(), (const __nv_fp8_e4m3*)k.data_ptr(), (const __nv_fp8_e4m3*)v.data_ptr(), \
2411	            (__nv_bfloat16*)out.data_ptr(), (float*)lse.data_ptr(),                                     \
2412	            (const int*)cu_q.data_ptr(), cu_k ? (const int*)cu_k->data_ptr() : nullptr,                 \
2413	            seqused_k ? (const int*)seqused_k->data_ptr() : nullptr,                                    \
2414	            paged ? (const int*)page_table->data_ptr() : nullptr,                                       \
2415	            q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,                                 \
2416	            hkv, rep, total_q, block_size, page_stride, (float)scale, causal ? 1 : 0,                   \
2417	            (float)softcap, win_l, win_r, num_splits, Opart, LSEpart, qd, kd, vd, ds_b, ds_h, MK_, MV_); \
2418	    } while (0)
2419	    if (fp8_tma_ok) {
2420	        CUtensorMap mapK = paged ? make_fp8_paged(k, block_size, true)  : make_fp8_contig(k, CTA_N, true);
2421	        CUtensorMap mapVst = paged ? make_fp8_paged(v, block_size, false) : make_fp8_contig(v, CTA_N, false);
2422	        FP8K_LAUNCH(true, mapK, mapVst);
2423	    } else {
2424	        CUtensorMap z{};
2425	        FP8K_LAUNCH(false, z, z);
2426	    }
2427	#undef FP8K_LAUNCH
2428	}
