2435	                               const std::optional<at::Tensor>& vd_,

2901	static void launch_decode_split_fp8(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2902	                                    at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2903	                                    const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2904	                                    const std::optional<at::Tensor>& page_table,
2905	                                    const std::optional<at::Tensor>& qd_, const std::optional<at::Tensor>& kd_,
2906	                                    const std::optional<at::Tensor>& vd_,
2907	                                    int b, int hq, int hkv, int total_q, int max_q, int max_klen, int cfg_splits,
2908	                                    double scale, bool causal, double softcap, int win_l, int win_r, cudaStream_t stream) {
2909	    using namespace pf;
2910	    const bool paged = page_table.has_value();
2911	    int rep = hq / hkv;
2912	    long q_row = q.stride(0), q_head = q.stride(1);
2913	    long k_row, k_head, v_row, v_head;
2914	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2915	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2916	    long o_row = out.stride(0), o_head = out.stride(1);
2917	    int block_size = paged ? (int)k.size(1) : 0;
2918	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2919	    int tiles_m = (max_q * rep + CTA_M - 1) / CTA_M;
2920	    const float* qd = qd_ ? (const float*)qd_->data_ptr() : nullptr;
2921	    const float* kd = kd_ ? (const float*)kd_->data_ptr() : nullptr;
2922	    const float* vd = vd_ ? (const float*)vd_->data_ptr() : nullptr;
2923	    int ds_b = qd_ ? (int)qd_->stride(0) : 0, ds_h = qd_ ? (int)qd_->stride(1) : 0;
2924	
2925	    int n_max_est = (max_klen + CTA_N - 1) / CTA_N;
2926	    int num_splits;
2927	    if (cfg_splits > 0) num_splits = cfg_splits;
2928	    else {
2929	        int dev = 0; cudaGetDevice(&dev);
2930	        int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2931	        int base = tiles_m * hkv * b;   // resident CTAs before splitting (fp8 decode runs 1 CTA/SM)
2932	        // Wave-quantization-aware: target the largest split count within ~one wave (sms CTAs); see
2933	        // launch_decode_split for the NCU sweep rationale (over-splitting past one wave regresses).
2934	        int want = std::max(1, sms / (base > 0 ? base : 1));
2935	        num_splits = std::min(want, 32);
2936	    }
2937	    if (num_splits > n_max_est) num_splits = std::max(1, n_max_est);
2938	
2939	    const bool extra = (softcap > 0.0) || (win_l >= 0) || (win_r >= 0);
2940	#define DS8(NS_, OP_, LP_)                                                                              \
2941	    do { if (extra) launch_prefill_fp8_t<HD, HDV, true>(q, k, v, out, lse, cu_q, cu_k, seqused_k,        \
2942	                page_table, hkv, rep, total_q, block_size, page_stride, tiles_m, b, scale, causal,       \
2943	                softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,       \
2944	                NS_, OP_, LP_, qd, kd, vd, ds_b, ds_h, stream);                                          \
2945	         else      launch_prefill_fp8_t<HD, HDV, false>(q, k, v, out, lse, cu_q, cu_k, seqused_k,        \
2946	                page_table, hkv, rep, total_q, block_size, page_stride, tiles_m, b, scale, causal,       \
2947	                softcap, win_l, win_r, q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head,       \
2948	                NS_, OP_, LP_, qd, kd, vd, ds_b, ds_h, stream); } while (0)
2949	    if (num_splits <= 1) { DS8(1, nullptr, nullptr); return; }
2950	    // LSEpart uninitialized (at::empty): empty splits stamp -inf via emit_empty_lse (see launch_decode_split).
2951	    auto fopt = q.options().dtype(at::kFloat);
2952	    at::Tensor Opart = at::empty({(long)num_splits, total_q, hq, HDV}, fopt);
2953	    at::Tensor LSEpart = at::empty({(long)num_splits, hq, total_q}, fopt);
2954	    float* opd = (float*)Opart.data_ptr(); float* lpd = (float*)LSEpart.data_ptr();
2955	    DS8(num_splits, opd, lpd);
2956	#undef DS8
2957	    dec::combine_kernel<__nv_bfloat16, HDV><<<dim3((unsigned)(total_q * hq), (unsigned)dec::combine_nb(HDV)), dec::COMBINE_THREADS, 0, stream>>>(
2958	        opd, lpd, (__nv_bfloat16*)out.data_ptr(), (float*)lse.data_ptr(), num_splits, total_q, hq, o_row, o_head);
2959	}
